from datetime import timedelta
from django.core.management.base import BaseCommand
from django.utils import timezone
from analytics.models import NewsItem, BusinessSignal

class Command(BaseCommand):
    help = "Create repeatable synthetic demo data for the dashboard."
    def handle(self, *args, **options):
        now = timezone.now()
        items = [
          ("ЦБ сохраняет жёсткий сигнал по инфляции", "Деловой контур", "Макроэкономика", "negative", 94, "Риторика регулятора указывает на то, что стоимость фондирования может оставаться повышенной дольше базового сценария. Следует перепроверить чувствительность маржи и кредитного спроса."),
          ("Ритейл ускоряет переход к собственным платёжным сценариям", "РБК", "Конкуренция", "neutral", 88, "Крупные торговые сети развивают собственные цифровые сервисы и программы лояльности. Это меняет борьбу за ежедневный контакт с клиентом."),
          ("Компании пересматривают инвестиционные планы на следующий квартал", "Коммерсантъ", "Корпоративный сектор", "negative", 86, "В отдельных отраслях появляются сигналы об отсрочке капитальных расходов. Возможен отложенный эффект на кредитование и транзакционную активность."),
          ("Рынок цифровых платежей растёт быстрее наличного оборота", "FinTech Review", "Технологии", "positive", 81, "Отраслевые обзоры указывают на рост цифровых платежей и новые точки интеграции в клиентский путь."),
          ("Экспортёры обсуждают новые маршруты поставок", "Интерфакс", "Внешняя торговля", "neutral", 78, "Перестройка логистики может перераспределить валютные потоки, потребность в гарантиях и расчётных инструментах."),
          ("Участники рынка отмечают рост мошеннических сценариев с дипфейками", "Безопасность сегодня", "Киберриски", "negative", 96, "Публикации описывают более убедительные схемы социальной инженерии. Это повод проверить сценарии защиты клиентов и коммуникационные предупреждения."),
          ("Малый бизнес активнее использует автоматизацию бухгалтерии", "Бизнес-практика", "Малый бизнес", "positive", 73, "Автоматизация финансовых операций становится частью повседневного инструментария малого бизнеса и создаёт возможности для сервисных интеграций."),
          ("Регуляторы обсуждают раскрытие рисков алгоритмических решений", "Право и технологии", "Регулирование", "neutral", 84, "Обсуждение может повлиять на требования к объяснимости, контролю качества данных и аудиту автоматизированных решений."),
          ("В промышленности увеличивается число запросов на оборотное финансирование", "Отраслевой обзор", "Корпоративный сектор", "positive", 70, "Сигнал о потенциальном изменении спроса на финансирование; необходима проверка по отраслевым и внутренним данным."),
          ("Клиенты ждут более понятного объяснения условий финансовых продуктов", "CX Monitor", "Клиентский опыт", "neutral", 76, "Публичные обсуждения подчёркивают важность прозрачного объяснения условий и своевременных подсказок в цифровых каналах."),
          ("Поставщики облачной инфраструктуры меняют условия обслуживания", "TechWire", "Технологии", "negative", 72, "Изменение тарифов у технологических поставщиков может повысить стоимость отдельных цифровых инициатив."),
          ("Региональные предприниматели отмечают осторожный спрос", "Деловая среда", "Малый бизнес", "negative", 68, "Сигналы из региональных обзоров указывают на неоднородность спроса. Обобщать их на весь рынок без дополнительной проверки нельзя.")]
        for i, (title, source, category, sentiment, relevance, summary) in enumerate(items):
          NewsItem.objects.get_or_create(title=title, is_demo=True, defaults={"source": source, "category": category, "sentiment": sentiment, "relevance": relevance, "summary": summary, "published_at": now-timedelta(hours=i*3+1), "url": ""})
        signals = [
          {"title":"Рост мошенничества может перейти из ИТ-риска в риск доверия", "horizon":"Ближайшие 2–4 недели", "severity":"high", "confidence":87, "impact_area":"Безопасность и клиентский опыт", "rationale":"В демонстрационной выборке сходятся публикации о дипфейках, социальной инженерии и запросе на более понятные предупреждения. Это не доказательство причинной связи, а проверяемая гипотеза для аналитика.", "next_step":"Сопоставить сигнал с обращениями клиентов и проверить сценарии предупреждений", "source_count":3},
          {"title":"Дорогие деньги могут одновременно давить на спрос и маржу", "horizon":"1–2 квартала", "severity":"high", "confidence":79, "impact_area":"Макроэкономика и кредитование", "rationale":"Сочетание жёсткого сигнала регулятора и новостей о пересмотре инвестиций может указывать на риск для спроса на финансирование. Требуется проверка на внутренних данных.", "next_step":"Проверить чувствительность отраслевых портфелей к сценарию высокой ставки", "source_count":2},
          {"title":"Изменение платёжных привычек усиливает конкуренцию за клиентский путь", "horizon":"1–2 квартала", "severity":"medium", "confidence":74, "impact_area":"Платежи и удержание клиентов", "rationale":"Новости о собственных платёжных сценариях ритейла и росте цифровых платежей описывают взаимосвязанные изменения пользовательского поведения.", "next_step":"Сравнить клиентские сценарии и определить точки потери контакта", "source_count":2},
          {"title":"Изменения в регулировании могут повысить требования к объяснимости ИИ", "horizon":"3–6 месяцев", "severity":"medium", "confidence":68, "impact_area":"Технологии и комплаенс", "rationale":"Обсуждение раскрытия алгоритмических рисков может стать ранним сигналом для пересмотра документации и контроля моделей.", "next_step":"Составить перечень затронутых автоматизированных решений и пробелов в аудите", "source_count":1}]
        for item in signals: BusinessSignal.objects.get_or_create(title=item["title"], is_demo=True, defaults=item)
        self.stdout.write(self.style.SUCCESS("Synthetic demo dataset is ready (idempotent)."))
